const crypto = require('crypto');

const payloadIn = $input.first().json || {};
const workflow = payloadIn.workflow && payloadIn.workflow.name ? payloadIn.workflow.name : 'unknown workflow';
const execution = payloadIn.execution || {};
const node = execution.lastNodeExecuted || 'unknown node';
const message = execution.error
  ? String(execution.error.message || execution.error.description || 'Workflow failed')
  : 'Workflow failed';
const executionId = execution.id ? String(execution.id) : 'unknown';
const executedAt = Date.now();

const secret = $env.LENDLOOP_HMAC_SECRET || '';
const base = ($env.LENDLOOP_CONVEX_SITE_URL || '').replace(/\/+$/, '');
const payload = JSON.stringify({
  kind: 'workflow.error',
  workflow,
  executionId,
  occurredAt: executedAt,
  message: message.slice(0, 400),
});
const timestamp = String(Math.floor(executedAt / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + payload).digest('hex');


const PALETTE = { brand: '#1F299C', navy: '#16215B', orange: '#F25929', muted: '#565B85', page: '#F4F6FC', rule: '#E4E8F5' };
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const LOGO = $env.LENDLOOP_LOGO_URL || 'https://lendloop-cdn.bahasha.app/email/logo-v2.png';
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function opsEmail(opts) {
  const rows = opts.rows.map(function (r) {
    return '<tr><td style="padding:5px 0;font:600 12px/18px ' + FONT + ';color:' + PALETTE.muted + ';white-space:nowrap;vertical-align:top;">' + esc(r[0]) + '</td>' +
      '<td style="padding:5px 0 5px 16px;font:400 13px/18px ' + FONT + ';color:' + PALETTE.navy + ';word-break:break-word;">' + esc(r[1]) + '</td></tr>';
  }).join('');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"></head>' +
    '<body style="margin:0;padding:0;background-color:' + PALETTE.page + ';">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:' + PALETTE.page + ';"><tr><td align="center" style="padding:32px 16px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#FFFFFF;border:1px solid ' + PALETTE.rule + ';border-radius:16px;">' +
    '<tr><td style="height:6px;line-height:6px;font-size:0;background-color:' + PALETTE.brand + ';border-radius:16px 16px 0 0;">&nbsp;</td></tr>' +
    '<tr><td style="padding:28px 32px 0 32px;"><img src="' + esc(LOGO) + '" width="140" height="30" alt="LendLoop" style="display:block;width:140px;max-width:140px;height:auto;border:0;"></td></tr>' +
    '<tr><td style="padding:24px 32px 0 32px;"><div style="font:700 11px/16px ' + FONT + ';letter-spacing:.10em;text-transform:uppercase;color:' + PALETTE.orange + ';">' + esc(opts.eyebrow) + '</div>' +
    '<h1 style="margin:8px 0 0 0;font:700 22px/30px ' + FONT + ';color:' + PALETTE.navy + ';">' + esc(opts.heading) + '</h1></td></tr>' +
    '<tr><td style="padding:18px 32px 0 32px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:' + PALETTE.page + ';border-radius:10px;"><tr><td style="padding:10px 14px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0">' + rows + '</table></td></tr></table></td></tr>' +
    '<tr><td style="padding:18px 32px 0 32px;"><p style="margin:0;font:400 13px/20px ' + FONT + ';color:' + PALETTE.muted + ';">' + esc(opts.note) + '</p></td></tr>' +
    '<tr><td style="padding:22px 32px 0 32px;"><a href="https://n8n.bahasha.app" style="display:inline-block;background-color:' + PALETTE.brand + ';border-radius:10px;padding:12px 22px;font:600 14px/18px ' + FONT + ';color:#FFFFFF;text-decoration:none;">Open n8n</a></td></tr>' +
    '<tr><td style="padding:26px 32px 26px 32px;"><div style="border-top:1px solid ' + PALETTE.rule + ';padding-top:14px;font:400 12px/18px ' + FONT + ';color:' + PALETTE.muted + ';">Internal alert from the LendLoop automation stack.</div></td></tr>' +
    '</table></td></tr></table></body></html>';
}

return [{
  json: {
    url: base + '/n8n/automation-events',
    payload,
    timestamp,
    signature,
    subject: 'LendLoop automation failed: ' + workflow,
    text: 'An n8n workflow failed.\n\nWorkflow: ' + workflow + '\nNode: ' + node + '\nError: ' + message + '\nExecution: ' + (execution.url || 'n/a') + '\n',
    html: opsEmail({ eyebrow: 'Automation', heading: 'Workflow failed: ' + workflow, rows: [['Workflow', workflow], ['Node', node], ['Error', message], ['Execution', execution.url || 'n/a']], note: 'The outbox keeps retrying on its own. Only act if this repeats, or if a notification stays undelivered.' }),
  },
}];

const crypto = require('crypto');

const item = $input.all()[0];
const headers = (item.json && item.json.headers) || {};
const b64 = item.binary && item.binary.data && item.binary.data.data;
const raw = typeof b64 === 'string' ? Buffer.from(b64, 'base64').toString('utf8') : '';
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const secret = $env.LENDLOOP_HMAC_SECRET || '';
const tolerance = Number($env.SIGNATURE_TOLERANCE_SECONDS || 300);

const fail = (reason) => [{ json: { valid: false, reason, body: null } }];

if (!secret) return fail('not_configured');
if (!raw) return fail('missing_body');
if (!/^\d{1,12}$/.test(timestamp)) return fail('bad_timestamp');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > tolerance) return fail('stale');
const match = /^v1=([0-9a-f]{64})$/.exec(signature);
if (!match) return fail('bad_signature');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex');
if (!crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(match[1]))) return fail('mismatch');

let body;
try {
  body = JSON.parse(raw);
} catch (error) {
  return fail('bad_json');
}
if (!body || typeof body !== 'object') return fail('bad_json');

return [{ json: { valid: true, reason: 'ok', body } }];

const alert = $json.body || {};


const PALETTE = { brand: '#1F299C', navy: '#16215B', orange: '#F25929', muted: '#565B85', page: '#F4F6FC', rule: '#E4E8F5' };
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const LOGO = $env.LENDLOOP_LOGO_URL || 'https://lendloop-cdn.bahasha.app/email/logo-v2.png';
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function opsEmail(opts) {
  const rows = opts.rows.map(function (r) {
    return '<tr><td style="padding:5px 0;font:600 12px/18px ' + FONT + ';color:' + PALETTE.muted + ';white-space:nowrap;vertical-align:top;">' + esc(r[0]) + '</td>' +
      '<td style="padding:5px 0 5px 16px;font:400 13px/18px ' + FONT + ';color:' + PALETTE.navy + ';word-break:break-word;">' + esc(r[1]) + '</td></tr>';
  }).join('');
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"></head>' +
    '<body style="margin:0;padding:0;background-color:' + PALETTE.page + ';">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:' + PALETTE.page + ';"><tr><td align="center" style="padding:32px 16px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px;max-width:600px;background:#FFFFFF;border:1px solid ' + PALETTE.rule + ';border-radius:16px;">' +
    '<tr><td style="height:6px;line-height:6px;font-size:0;background-color:' + PALETTE.brand + ';border-radius:16px 16px 0 0;">&nbsp;</td></tr>' +
    '<tr><td style="padding:28px 32px 0 32px;"><img src="' + esc(LOGO) + '" width="140" height="30" alt="LendLoop" style="display:block;width:140px;max-width:140px;height:auto;border:0;"></td></tr>' +
    '<tr><td style="padding:24px 32px 0 32px;"><div style="font:700 11px/16px ' + FONT + ';letter-spacing:.10em;text-transform:uppercase;color:' + PALETTE.orange + ';">' + esc(opts.eyebrow) + '</div>' +
    '<h1 style="margin:8px 0 0 0;font:700 22px/30px ' + FONT + ';color:' + PALETTE.navy + ';">' + esc(opts.heading) + '</h1></td></tr>' +
    '<tr><td style="padding:18px 32px 0 32px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width:100%;background-color:' + PALETTE.page + ';border-radius:10px;"><tr><td style="padding:10px 14px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0">' + rows + '</table></td></tr></table></td></tr>' +
    '<tr><td style="padding:18px 32px 0 32px;"><p style="margin:0;font:400 13px/20px ' + FONT + ';color:' + PALETTE.muted + ';">' + esc(opts.note) + '</p></td></tr>' +
    '<tr><td style="padding:22px 32px 0 32px;"><a href="https://n8n.bahasha.app" style="display:inline-block;background-color:' + PALETTE.brand + ';border-radius:10px;padding:12px 22px;font:600 14px/18px ' + FONT + ';color:#FFFFFF;text-decoration:none;">Open n8n</a></td></tr>' +
    '<tr><td style="padding:26px 32px 26px 32px;"><div style="border-top:1px solid ' + PALETTE.rule + ';padding-top:14px;font:400 12px/18px ' + FONT + ';color:' + PALETTE.muted + ';">Internal alert from the LendLoop automation stack.</div></td></tr>' +
    '</table></td></tr></table></body></html>';
}

return [{
  json: {
    subject: 'LendLoop automation alert',
    text: 'LendLoop could not deliver a notification.\n\nWorkflow: ' + (alert.workflow || 'unknown') + '\nError: ' + (alert.message || 'unknown') + '\nLoan: ' + (alert.loanRequestId || 'n/a') + '\nWhen: ' + new Date(alert.occurredAt || Date.now()).toISOString() + '\n',
    html: opsEmail({ eyebrow: 'Delivery failed', heading: 'A notification could not be delivered', rows: [['Workflow', alert.workflow || 'unknown'], ['Error', alert.message || 'unknown'], ['Loan', alert.loanRequestId || 'n/a'], ['When', new Date(alert.occurredAt || Date.now()).toISOString()]], note: 'The outbox exhausted its retries for this row. The borrower or owner has not been told about this event.' }),
  },
}];
